function placeModal(placeID=''){if(!canWrite())return;const p=state.places[placeID]||{id:id(),name:'',note:'',version:0};modal(p.version?'Изменить место':'Новое место хранения','Это может быть склад, помещение, стеллаж или полка.',`<form id="place-form" class="stack"><label class="field">Название<input class="input" name="name" required maxlength="100" value="${esc(p.name)}" placeholder="Склад А / Стеллаж 02 / Полка 3"></label><label class="field">Описание<textarea name="note" maxlength="200">${esc(p.note)}</textarea></label></form>`,formButtons('place-form'));$('#place-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runForm(f,async()=>{const d=new FormData(f),place={...p,name:String(d.get('name')),note:String(d.get('note'))};const r=await send({id:id(),type:'place',place});toast(r.saved?'Место сохранено.':'Место ждёт подтверждения.',r.saved?'':'warn');});});}
