 s=D.execute(s,{id:id(),type:'transfer',itemId:'demo-item-2',from:'main-place',to:'workshop-place',qty:40000,note:'Передача на участок · пример'});s=D.execute(s,{id:id(),type:'out',itemId:'demo-item-1',from:'main-place',qty:25000,note:'В производство · пример'});
