async function copyText(text,element){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);toast('Скопировано.');return;}}catch{}if(element){element.focus();element.select();try{if(document.execCommand('copy')){toast('Скопировано.');return;}}catch{}}toast('Выделите текст и скопируйте его вручную.','warn');}
function downloadText(name,text,type='application/json'){
 if(window.chrome?.webview){window.chrome.webview.postMessage({kind:'saveText',name,text,mime:type});return;}
 if(window.AndroidFiles&&typeof AndroidFiles.saveText==='function'){AndroidFiles.saveText(name,text,type);toast('Выберите, куда сохранить файл.');return;}
 const blob=new Blob([text],{type:type+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
}
function showExport(name,text){modal('Резервная копия готова','Сохраните файл отдельно от устройства. Здесь также доступен текст копии.',`<div class="stack"><div class="notice">${esc(name)} · ${new Blob([text]).size.toLocaleString('ru-RU')} байт. Полная копия товаров, мест и истории. Паролей и токенов в этом файле нет.</div><button class="btn primary" id="save-export">${ic('download')}Сохранить файл</button><details><summary class="small">Запасной способ: скопировать текст</summary><textarea id="export-text" class="codearea" readonly style="margin-top:12px">${esc(text)}</textarea><button class="btn small" id="copy-export" style="margin-top:10px">Скопировать текст</button></details></div>`);$('#save-export').onclick=()=>downloadText(name,text);$('#copy-export').onclick=()=>copyText(text,$('#export-text'));}
function portableNativeInfo(){
 if(!window.AndroidFiles||typeof AndroidFiles.portableInfo!=='function')return {supported:false,attached:false,name:'',bytes:0};
 try{return {supported:true,...JSON.parse(AndroidFiles.portableInfo())};}catch{return {supported:true,attached:false,name:'',bytes:0,error:'Не удалось прочитать состояние файла.'};}
}
function portableSnapshot(value=state){
 if(!value)throw new Error('Склад ещё не создан.');const clean=D.copy(value);delete clean.localSeen;delete clean.me;delete clean.savedAt;clean.demo=false;clean.exportedAt=new Date().toISOString();clean.portable={format:1,appVersion:APP_VERSION,updatedAt:clean.exportedAt};D.validateBackup(clean);return JSON.stringify(clean,null,2);
}
function portableFileName(){const base=String(state?.space?.name||'Мой-склад').replace(/[<>:"/\\|?*\x00-\x1F]/g,' ').trim().replace(/\s+/g,'-').slice(0,50)||'Мой-склад';return `YARUS-${base}.yarus.json`;}
function portableStorageHTML(){
 if(isShared())return `<div class="portable-box"><h3>Отдельный файл личного склада</h3><p class="small muted">Для общего склада главным остаётся сервер. Его переносят только защищённым файлом .yarus, чтобы не создать две независимые базы.</p></div>`;
 const info=portableNativeInfo();
 if(!info.supported)return `<div class="portable-box"><h3>Файл склада отдельно от приложения</h3><p class="small muted">Формат <b>.yarus.json</b> открывается на Windows и Android. В этой версии Windows файл сохраняется и открывается вручную.</p><div class="stack"><button class="btn" data-action="portable-create">${ic('download')}Сохранить универсальный файл</button><button class="btn" data-action="portable-open">${ic('upload')}Открыть файл склада</button></div></div>`;
 if(info.attached)return `<div class="portable-box"><h3>Файл склада отдельно от приложения</h3><div class="notice ${info.error?'warn':''}"><b>${esc(info.name||'Файл подключён')}</b><br>${info.error?esc(info.error):'Обновляется автоматически после каждого изменения.'}${Number(info.bytes)>=0?'<br>Размер: '+esc(formatBytes(info.bytes)):''}</div><div class="stack"><button class="btn" data-action="portable-sync">${ic('refresh')}Обновить файл сейчас</button><button class="btn" data-action="portable-open">${ic('upload')}Подключить другой файл</button><button class="btn" data-action="portable-detach">Отключить файл, не удаляя его</button></div><p class="small muted">Файл находится вне ЯРУС и переживёт удаление приложения. После переустановки выберите его снова. Он содержит товары и историю, но не пароли.</p></div>`;
 return `<div class="portable-box"><h3>Файл склада отдельно от приложения</h3><p>Создайте внешний файл один раз. Android будет обновлять его после каждого изменения, а удаление приложения файл не сотрёт.</p><div class="stack"><button class="btn primary" data-action="portable-create">${ic('file')}Создать и подключить файл</button><button class="btn" data-action="portable-open">${ic('upload')}Открыть существующий файл</button></div><p class="small muted">Храните файл только в доверенной папке: в нём есть товары, места и история, но нет паролей.</p></div>`;
}
async function installPortableState(value,name='',attach=false){
 const restored=D.validateBackup(typeof value==='string'?JSON.parse(value):value);if(state&&cfg.mode==='remote'&&queue.length)throw new Error('Сначала разберите очередь общего склада.');
 if(cfg.mode==='host')throw new Error('На главном устройстве общий склад нельзя заменить личным файлом. Сначала перенесите роль главного устройства.');
 if(cfg.mode==='remote'&&!confirm(`Открыть личный склад из файла «${name||'ЯРУС'}» и выйти из общего склада на этом устройстве? Общая база на главном устройстве не изменится.`))throw new Error('Открытие файла отменено.');
 if(cfg.mode!=='remote'&&state&&((state.events?.length||0)||Object.keys(state.items||{}).length)&&!confirm(`Открыть склад из файла «${name||'ЯРУС'}»? Текущий личный склад будет заменён, но перед заменой сохранится внутренняя копия.`))throw new Error('Открытие файла отменено.');
 if(state)await putKV('before-restore',state);await putKV('local',restored);state=restored;cfg.mode='local';cfg.demo=false;delete cfg.token;saveCfg();queue=[];network='local';page='home';$('#app').innerHTML='';render();
 if(attach&&window.AndroidFiles&&typeof AndroidFiles.confirmPortable==='function'){const result=String(AndroidFiles.confirmPortable()||'');if(result.startsWith('!ERROR:'))throw new Error(result.slice(7));await mirrorPortableState();}
 toast(attach?'Файл подключён. Теперь он обновляется автоматически.':'Склад открыт из универсального файла.');
}
async function openPortableWarehouse(){
 if(window.AndroidFiles&&typeof AndroidFiles.openPortable==='function'){AndroidFiles.openPortable();return;}
 const input=document.createElement('input');input.type='file';input.accept='.json,.yarus.json,application/json';input.className='visually-hidden';document.body.append(input);input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;if(file.size>32e6)throw new Error('Файл склада больше 32 МБ.');await installPortableState(await file.text(),file.name,false);}catch(e){toast(e.message,'error');}finally{input.remove();}};input.click();
}
async function createPortableWarehouse(){
 if(!state||isShared()||cfg.demo){toast('Отдельный файл подключается только к своему личному складу.','warn');return;}const text=portableSnapshot();
 if(window.AndroidFiles&&typeof AndroidFiles.createPortable==='function'){AndroidFiles.createPortable(portableFileName(),text);return;}showExport(portableFileName(),text);
}
async function mirrorPortableState(show=false){
 if(!state||isShared()||cfg.demo||!window.AndroidFiles||typeof AndroidFiles.writePortable!=='function')return false;const info=portableNativeInfo();if(!info.attached)return false;
 try{const error=String(AndroidFiles.writePortable(portableSnapshot())||'');if(error)throw new Error(error);if(show)toast('Внешний файл склада обновлён.');return true;}catch(e){if(show||Date.now()-portableWriteWarningAt>60000){portableWriteWarningAt=Date.now();toast(e.message||'Внутренняя база сохранена, но внешний файл не обновлён.','warn');}return false;}
}
function detachPortableWarehouse(){if(!window.AndroidFiles||typeof AndroidFiles.detachPortable!=='function')return;if(!confirm('Отключить внешний файл? Сам файл останется на устройстве, но больше не будет обновляться автоматически.'))return;AndroidFiles.detachPortable();render();toast('Файл отключён и не удалён.');}
window.YarusPortable={
 created(info,error){if(error){toast(error,'error');return;}toast('Файл создан вне приложения и подключён.');if(page==='settings')render();},
 async opened(text,name){try{await installPortableState(text,name,true);}catch(e){try{AndroidFiles.cancelPortable();}catch{}if(e.message!=='Открытие файла отменено.')toast(e.message,'error');}},
 failed(unused,error){toast(error||'Не удалось открыть файл склада.','error');},
 cancelled(){},
};
async function backup(){try{let s=isShared()?await api('/api/export'):D.copy(state);delete s.localSeen;delete s.me;delete s.savedAt;s.demo=false;s.exportedAt=new Date().toISOString();const text=JSON.stringify(s,null,2),name='YARUS-backup-'+new Date().toISOString().slice(0,10)+'.json';D.validateBackup(s);showExport(name,text);}catch(e){toast(e.network?'Для полной копии общего склада нужен работающий сервер.':e.message,'error');}}
function restoreModal(){if(isShared()){toast('Локальное восстановление недоступно для общего склада. Используйте защищённый перенос главного устройства.','warn');return;}modal('Восстановить локальную копию','Копия заменит текущий локальный склад, не объединится с ним.',`<form id="restore-form" class="stack"><label class="field">Выберите JSON-файл<input class="input" id="restore-file" type="file" accept=".json,.yarus.json,application/json"></label><label class="field">Или вставьте текст резервной копии<textarea class="codearea" id="restore-text" placeholder="Текст из файла ЯРУС"></textarea></label><div class="notice warn">До замены будет сохранена внутренняя копия «до восстановления». Внешняя копия всё равно нужна на случай удаления приложения.</div><label class="row small"><input type="checkbox" required> Я понимаю, что текущий локальный склад будет заменён.</label></form>`,formButtons('restore-form','Проверить и восстановить'));
 $('#restore-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runForm(f,async()=>{const file=$('#restore-file').files[0];if(file&&file.size>32e6)throw new Error('Максимальный файл — 32 МБ.');const text=file?await file.text():$('#restore-text').value;const s=D.validateBackup(JSON.parse(text));await putKV('before-restore',state);await putKV(activeKey(),s);state=s;cfg.demo=false;cfg.mode='local';saveCfg();await putKV('local',s);await mirrorPortableState();page='home';$('#app').innerHTML='';render();toast('Копия проверена. Локальный склад восстановлен.');});});}
function exportCSV(history=false){let rows;if(history){rows=[['Дата UTC','Операция','Товар','Артикул','Откуда','Куда','Количество / факт','Единица','Участник','Комментарий','Документ']];for(const e of state.events){const x=state.items[e.item];rows.push([e.at,names[e.kind],x?.name,x?.sku,placeName(e.from),placeName(e.to),decimalString(e.qty),x?.unit,e.actorName,e.note,e.ref]);}}
 else{rows=[['Название','Артикул','Категория','Место','Остаток','Единица','Минимум общий','Цена справочная','Валюта','Штрихкод']];for(const x of activeItems())for(const p of Object.values(state.places)){rows.push([x.name,x.sku,x.category,p.name,decimalString(itemTotal(x,p.id)),x.unit,decimalString(x.min),decimalString(x.price,2),state.space.currency,x.barcode]);}}
 const text='\uFEFF'+rows.map(r=>r.map(D.csvCell).join(';')).join('\r\n');downloadText(history?'YARUS-movements.csv':'YARUS-stock.csv',text,'text/csv');if(history&&isShared())toast('Экспортирована загруженная история: до 1000 последних записей. Полная — в резервной копии.','warn');}
function stockReportModal(){const visible=filteredItems().filter(item=>!item.archived);modal('Отчёт об остатках в PDF','Файл создаётся локально на этом устройстве.',`<form id="report-form" class="stack"><label class="field">Вид отчёта<select name="layout"><option value="summary">Сводно по товарам</option><option value="places">Подробно по местам хранения</option></select></label><label class="field">Какие товары<select name="scope"><option value="current">Текущий поиск и фильтры (${visible.length})</option><option value="all">Все активные товары</option></select></label><div class="notice">В отчёте будут текущие подтверждённые остатки, минимумы и справочная оценка. Для общего склада сначала убедитесь, что статус - «Синхронизировано».</div><div id="report-progress" class="small muted" role="status"></div></form>`,formButtons('report-form','Сформировать PDF'));$('#report-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;runForm(form,async()=>{const data=new FormData(form),current=data.get('scope')==='current',layout=String(data.get('layout')),options={layout,itemIds:current?visible.map(item=>item.id):undefined,placeId:current?placeFilter:'',scopeLabel:current?'Текущий поиск и фильтры':'Все активные товары',onProgress:(done,total)=>{const progress=$('#report-progress');if(progress)progress.textContent='Готовим страницу '+done+' из '+total+'...';}};const pdf=await YarusReports.stockPDF(state,options),date=new Date().toISOString().slice(0,10);downloadText('YARUS-stock-'+date+'-'+layout+'.pdf',pdf,'application/pdf');toast('Отчёт сформирован. Выберите папку для сохранения.');});});}
let importPrepared=[];
function importModal(){if(!canWrite())return;importPrepared=[];modal('Импорт каталога из CSV','Создаёт карточки. Остатки вводятся отдельно через приход.',`<form id="import-form" class="stack"><div class="notice">Столбцы: <b>Название;Артикул;Категория;Единица;Минимум;Цена;Штрихкод</b>. Артикул обязателен для защиты от повторного импорта. До 500 строк за раз.</div><button type="button" class="btn" id="csv-template">${ic('download')}Скачать шаблон</button><label class="field">CSV-файл в UTF-8<input class="input" id="csv-file" type="file" accept=".csv,text/csv" required></label><div id="csv-preview" class="small muted">Выберите файл для предварительной проверки.</div><div class="notice warn">Общий склад импортирует строки по одной, не одним документом. При потере связи проверьте очередь и фактически созданные карточки перед повтором.</div></form>`,formButtons('import-form','Импортировать карточки'),true);
 $('#csv-template').onclick=()=>downloadText('YARUS-catalog-template.csv','\uFEFFНазвание;Артикул;Категория;Единица;Минимум;Цена;Штрихкод\r\nКанистра 5 л;УП-005;Упаковка;шт;20;48;\r\n','text/csv');
 $('#csv-file').onchange=async()=>{try{const f=$('#csv-file').files[0];if(!f)return;if(f.size>2e6)throw new Error('Файл больше 2 МБ.');const rows=D.parseCSV(await f.text());if(rows.length<2||rows.length>501)throw new Error('Нужно от 1 до 500 строк данных.');const header=rows[0].map(x=>x.trim().toLowerCase());const expected=['название','артикул','категория','единица','минимум','цена','штрихкод'];if(expected.some(x=>!header.includes(x)))throw new Error('Заголовки отличаются от шаблона. Скачайте шаблон и перенесите столбцы.');
 let temporary=D.copy(state);const commands=[];for(let n=1;n<rows.length;n++){const get=h=>(rows[n][header.indexOf(h)]||'').trim();if(!get('артикул'))throw new Error('Строка '+(n+1)+': укажите артикул.');const item={id:id(),name:get('название'),sku:get('артикул'),category:get('категория'),unit:get('единица')||'шт',min:D.decimal(get('минимум')||'0'),price:D.decimal(get('цена')||'0',2),barcode:get('штрихкод'),note:'',fields:{},archived:false,version:0};const c={id:id(),type:'item',item};try{temporary=D.execute(temporary,c);}catch(e){throw new Error('Строка '+(n+1)+': '+e.message);}commands.push(c);}
 importPrepared=commands;$('#csv-preview').innerHTML=`<span class="tag">${commands.length} карточек прошли проверку</span><div style="margin-top:12px">${commands.slice(0,8).map(c=>esc(c.item.name)+' · '+esc(c.item.sku)).join('<br>')}${commands.length>8?'<br>…':''}</div>`;$('#form-error').textContent='';
 }catch(e){importPrepared=[];formError(e);}};
 $('#import-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runForm(f,async()=>{if(!importPrepared.length)throw new Error('Сначала выберите и проверьте CSV.');let done=0;for(const c of importPrepared){try{const r=await send(c);if(!r.saved)throw new Error('Связь прервалась. Строка сохранена в очереди; остальные не отправлялись.');done++;}catch(e){throw new Error(`Подтверждено ${done} из ${importPrepared.length}. ${e.message}`);}}toast('Импортировано карточек: '+done+'. Остатки ещё не введены.');});});}
function createHostModal(){if(!window.YarusAndroidHost){toast('Главное мобильное устройство доступно в приложении Android.','warn');return;}if(YarusAndroidHost.info().exists){openHost();return;}modal('Сделать это устройство главным','Оно будет хранить общую базу и принимать изменения коллег.',`<form id="host-create-form" class="stack"><label class="field">Название склада<input class="input" name="space" required maxlength="80" value="Мой склад"></label><label class="field">Название устройства<input class="input" name="device" required maxlength="80" value="Мой телефон"><small>Например: «Планшет в мастерской».</small></label><label class="field">Ваше имя<input class="input" name="name" required maxlength="80"></label><label class="field">Логин владельца<input class="input" name="login" required minlength="3" maxlength="80" autocomplete="username" autocapitalize="none"></label><label class="field">Пароль владельца<input class="input" name="password" type="password" required minlength="10" maxlength="256" autocomplete="new-password"></label><div class="notice warn"><b>Важно:</b> другие устройства подключаются только пока ЯРУС открыт, телефон включён и находится в доступной сети. Для постоянно работающего склада надёжнее компьютер.</div><label class="row small"><input type="checkbox" required> Я понимаю, когда коллеги смогут подключаться.</label></form>`,formButtons('host-create-form','Создать общий склад'));
 $('#host-create-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runForm(f,async()=>{const d=new FormData(f),res=await YarusAndroidHost.create({space:String(d.get('space')),device:String(d.get('device')),name:String(d.get('name')),login:String(d.get('login')),password:String(d.get('password'))});cfg={...cfg,mode:'host',server:'android-host',token:res.token,hostToken:res.token,login:res.state.me.login,demo:false};saveCfg();queue=[];network='host';state=null;await acceptState(res.state);page='home';$('#app').innerHTML='';render();toast('Это устройство стало главным. Создайте приглашение для остальных.');});});}
function hostLoginModal(){modal('Войти в главный склад','База уже находится на этом устройстве. Введите данные владельца или участника.',`<form id="host-login-form" class="stack"><label class="field">Логин<input class="input" name="login" required autocomplete="username" autocapitalize="none"></label><label class="field">Пароль<input class="input" name="password" type="password" required autocomplete="current-password"></label></form>`,formButtons('host-login-form','Войти'));$('#host-login-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runForm(f,async()=>{const d=new FormData(f),res=await YarusAndroidHost.request('/api/login',{method:'POST',body:{login:String(d.get('login')),password:String(d.get('password'))}});cfg={...cfg,mode:'host',server:'android-host',token:res.token,hostToken:res.token,login:res.state.me.login,demo:false};saveCfg();state=null;queue=[];network='host';await acceptState(res.state);page='home';$('#app').innerHTML='';render();});});}
async function openHost(){if(!window.YarusAndroidHost||!YarusAndroidHost.info().exists){createHostModal();return;}YarusAndroidHost.activate();const token=cfg.hostToken||cfg.token;if(!token){hostLoginModal();return;}try{const res=await YarusAndroidHost.request('/api/state',{authorization:'Bearer '+token});cfg={...cfg,mode:'host',server:'android-host',token,hostToken:token,login:res.me.login,demo:false};saveCfg();state=null;queue=[];network='host';await acceptState(res);page='home';$('#app').innerHTML='';render();}catch{hostLoginModal();}}
function importHostModal(){modal('Перенести сюда главный склад','Файл расшифруется только на этом устройстве. Код нужен один раз и не сохраняется.',`<form id="host-import-form" class="stack"><label class="field">Защищённый файл ЯРУС<input class="input" id="host-import-file" type="file" accept=".yarus,application/vnd.yarus+json" required></label><label class="field">Код защиты<input class="input" name="code" required minlength="16" maxlength="80" autocapitalize="characters" spellcheck="false" placeholder="XXXX-XXXX-XXXX-XXXX-XXXX"></label><div class="notice">Перенос не объединяет две базы. Он открывается только на пустом главном устройстве и сохраняет товары, историю, пользователей и пароли входа.</div><label class="row small"><input type="checkbox" required> Я выбрал файл именно того склада, который хочу сделать главным здесь.</label></form>`,formButtons('host-import-form','Расшифровать и перенести'));
 $('#host-import-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runForm(f,async()=>{const file=$('#host-import-file').files[0];if(!file)throw new Error('Выберите файл .yarus.');if(file.size>48*1024*1024)throw new Error('Файл больше допустимых 48 МБ.');const opened=await YarusTransfer.decrypt(await file.text(),String(new FormData(f).get('code')),'host-transfer');let res,mode,server;if(window.YarusAndroidHost){if(YarusAndroidHost.info().exists)throw new Error('На Android уже есть главный склад. Перенос возможен только в пустое хранилище.');res=await YarusAndroidHost.importTransfer(opened.payload);mode='host';server='android-host';}else{if(!setupKey)throw new Error('На компьютере откройте новую пустую папку ЯРУС и запустите приложение переноса из неё.');server=normalizeServer(inferServer());res=await api('/api/transfer/import',{setup:setupKey,transfer:opened.payload},server,'');mode='remote';}cfg={...cfg,mode,server,token:res.token,hostToken:mode==='host'?res.token:cfg.hostToken,login:res.state.me.login,demo:false};saveCfg();state=null;queue=[];network=mode==='host'?'host':'online';await acceptState(res.state);page='home';$('#app').innerHTML='';render();toast('Главный склад перенесён. Старое устройство осталось только для чтения.');});});}
async function hostTransferModal(){if(!isMainDevice()||!can('host_transfer')){toast('Перенос запускает владелец именно на текущем главном устройстве.','warn');return;}let storage;try{storage=await api('/api/storage');}catch(e){toast(e.message,'error');return;}const seconds=Math.max(2,Math.ceil(Number(storage.packageBytes||0)/500000));modal('Передать главный склад','Без объединения и без дубликатов: старое устройство станет копией только для чтения.',`<form id="host-transfer-form" class="stack"><label class="field">Как назвать новое главное устройство<input class="input" name="device" required maxlength="80" placeholder="Например, Компьютер в офисе"></label><div class="notice">Будет перенесено: <b>${formatBytes(storage.packageBytes)}</b>, ${storage.items} товаров, ${storage.events} движений. Подготовка обычно занимает около ${seconds}–${seconds+5} сек. На новом устройстве желательно не меньше ${formatBytes(Math.max(storage.packageBytes*3,10485760))} свободного места.</div><div class="notice warn"><b>После подтверждения этот экземпляр перестанет принимать изменения.</b> Сначала сохраните файл .yarus, затем на новом устройстве выберите «Перенести сюда главный склад» и введите показанный код.</div><label class="row small"><input type="checkbox" required> Я понимаю, что старое устройство станет только копией для чтения.</label></form>`,formButtons('host-transfer-form','Подготовить защищённый перенос'));
 $('#host-transfer-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,button=$(`button[form="${f.id}"]`),old=button.innerHTML;button.disabled=true;button.textContent='Шифруем базу…';try{const device=String(new FormData(f).get('device')).trim();if(!device)throw new Error('Укажите название нового устройства.');const transfer=cfg.mode==='host'?await YarusAndroidHost.transferState(device):(await api('/api/transfer/prepare',{device})).transfer,recovery=YarusTransfer.code(),secured=await YarusTransfer.encrypt(transfer,recovery,'host-transfer'),text=JSON.stringify(secured);state.host={...state.host,status:'retired'};modalDirty=false;closeModal(true);render();preparedTransferModal(text,recovery);}catch(err){formError(err);button.disabled=false;button.innerHTML=old;}});}
function preparedTransferModal(text,recovery){const name='YARUS-main-device-'+new Date().toISOString().slice(0,10)+'.yarus';modal('Защищённый перенос готов','Сохраните файл и код. Без кода файл невозможно открыть.',`<div class="stack"><div class="notice"><b>${esc(name)}</b> · ${formatBytes(YarusTransfer.byteLength(text))}</div><label class="field">Код защиты<textarea class="codearea" id="transfer-code" readonly style="min-height:72px;font-size:18px">${esc(recovery)}</textarea><small>Передайте код отдельно от файла. ЯРУС его не хранит и восстановить его не сможет.</small></label><button class="btn primary" id="save-transfer">${ic('download')}Сохранить файл .yarus</button><button class="btn" id="copy-transfer-code">${ic('copy')}Скопировать код</button><div class="notice warn">Не удаляйте файл и не очищайте старое приложение, пока новый главный склад не откроется и вы не проверите остатки.</div></div>`);$('#save-transfer').onclick=()=>downloadText(name,text,'application/vnd.yarus+json');$('#copy-transfer-code').onclick=()=>copyText(recovery,$('#transfer-code'));}
async function teamModalV11(){if(!isShared()){accountModal();return;}if(!can('team')){toast('У вас нет права управлять участниками.','warn');return;}try{const info=await api('/api/team');let addrs=info.addresses||[];if(cfg.mode==='remote'&&!/^https?:\/\/(127\.|localhost)/.test(cfg.server))addrs=[cfg.server,...addrs.filter(x=>x!==cfg.server)];if(!addrs.length)addrs=cfg.mode==='host'?YarusAndroidHost.info().addresses:[cfg.server];
 modal('Участники и приглашения','Выберите понятный уровень доступа. Владельца нельзя заменить или понизить.',`<div class="stack"><label class="field">Адрес для подключения<select id="invite-address">${addrs.map((a,i)=>`<option value="${esc(a)}">${esc(a)}${i===0?' — рекомендуется':''}</option>`).join('')}</select><small>Первым ЯРУС ставит наиболее вероятный адрес Wi‑Fi/Ethernet. Если телефон не подключается, выберите другой адрес и создайте новый QR. Через интернет нужен настроенный HTTPS.</small></label><div class="row wrap"><select id="invite-role" aria-label="Права приглашения"><option value="admin">Администратор — почти всё, кроме смены владельца и переноса</option><option value="manager" selected>Менеджер — каталог, места и движения</option><option value="operator">Кладовщик — только движения</option><option value="viewer">Только просмотр</option></select><button class="btn primary" data-action="make-invite">Пригласить</button></div><div id="invite-result"></div><div>${info.users.map(u=>`<div class="setting-row"><div class="row"><div class="avatar">${esc(u.name.slice(0,1).toUpperCase())}</div><div><h3>${esc(u.name)}</h3><p>${esc(u.login)} · ${roleName[u.role]||u.role}${u.disabled?' · отключён':''}</p></div></div>${u.role!=='owner'&&!u.disabled?`<div class="row wrap"><select id="role-${u.id}" aria-label="Роль ${esc(u.name)}">${[['admin','Администратор'],['manager','Менеджер'],['operator','Кладовщик'],['viewer','Просмотр']].map(([v,t])=>`<option value="${v}" ${u.role===v||u.role==='editor'&&v==='manager'?'selected':''}>${t}</option>`).join('')}</select><button class="btn small" data-action="change-role" data-id="${u.id}">Изменить</button><button class="btn small danger" data-action="disable-user" data-id="${u.id}">Отключить</button></div>`:'<span class="tag">Владелец</span>'}</div>`).join('')}</div><div class="notice">Приглашение действует 24 часа и используется один раз. Отключение запрещает новые запросы, но не удаляет уже сохранённую копию с чужого устройства.</div></div>`,'',true);
 }catch(e){toast(e.network?'Нет связи с главным устройством.':e.message,'error');}}
async function makeInviteV11(){const btn=$('[data-action="make-invite"]');btn.disabled=true;try{const res=await api('/api/invite',{role:$('#invite-role').value}),address=$('#invite-address').value,payload=YarusCodes.invite(address,res.code,res.expires),expires=new Date(res.expires*1000);$('#invite-result').innerHTML=`<div class="notice"><b>Покажите QR только доверенному человеку.</b> Код одноразовый и действует до ${esc(niceDate(expires.toISOString(),true))}.</div><div class="invite-qr" id="invite-qr" aria-label="QR-приглашение"></div><textarea class="codearea" id="invite-text" readonly style="min-height:120px">${esc('ЯРУС — приглашение в склад «'+state.space.name+'»\nАдрес: '+address+'\nКод: '+res.code+'\nРоль: '+roleName[$('#invite-role').value]+'\nДействует до: '+expires.toLocaleString('ru-RU'))}</textarea><div class="invite-actions"><button class="btn small" data-action="copy-invite">${ic('copy')}Скопировать текст</button><button class="btn small" id="save-invite-qr">${ic('download')}Сохранить QR</button></div>`;$('#invite-qr').innerHTML=YarusCodes.svg(payload);$('#save-invite-qr').onclick=()=>downloadText('YARUS-invite.svg',YarusCodes.svg(payload),'image/svg+xml');}catch(e){formError(e);}finally{btn.disabled=false;}}
function openExternal(value){try{if(window.AndroidFiles?.openExternal(value))return;if(window.chrome?.webview){window.chrome.webview.postMessage({kind:'openExternal',value});return;}window.open(value,'_blank','noopener');}catch{copyText(value);}}
function helpModal(){modal('Как пользоваться ЯРУС','Понятные шаги с мощным и безопасным учётом под капотом.',`<div class="help-item"><h3>1. Выберите, где хранится главная база</h3><p>Для команды одно устройство является главным. Лучше постоянно включённый компьютер. Телефон или планшет тоже подходит, но коллеги подключаются только пока ЯРУС открыт и устройство доступно в сети. Личный склад ни с кем не синхронизируется.</p></div><div class="help-item"><h3>2. Добавьте товары и места</h3><p>Товар — это «что», место — «где». Начальный остаток оформите приходом. Нельзя тихо переписать число: каждое изменение остаётся в истории.</p></div><div class="help-item"><h3>3. Подключите людей</h3><p>На главном устройстве откройте «Настройки → Участники», выберите роль и создайте приглашение. Передайте QR или адрес с одноразовым кодом. Владелец один; администратор умеет почти всё, но не может стать владельцем или передать главный склад.</p></div><div class="help-item"><h3>4. Что будет без связи</h3><p>Подключённое устройство показывает последнюю подтверждённую копию. Новые операции остаются заметными черновиками и не меняют остаток, пока главное устройство их не примет. Телефон-главное устройство перестаёт быть доступен после закрытия ЯРУС.</p></div><div class="help-item"><h3>5. Как перенести главный склад</h3><p>Владелец запускает перенос на старом главном устройстве. Оно сразу становится копией только для чтения. ЯРУС создаёт зашифрованный файл .yarus и отдельный длинный код. На новом пустом устройстве выберите «Перенести сюда главный склад» и один раз введите код. Базы не объединяются — так не появляются двойные движения.</p></div><div class="help-item"><h3>6. Файл личного склада и копии</h3><p>На Android создайте в настройках внешний .yarus.json: он автоматически обновляется и остаётся после удаления приложения. После переустановки выберите его на первом экране. Файл содержит товары и историю без паролей, но не зашифрован. Файл переноса .yarus содержит также пользователей и всегда шифруется AES‑256‑GCM; код храните отдельно.</p></div><div class="help-item"><h3>7. QR, штрихкоды и PDF</h3><p>Камера включается только по вашей кнопке. Можно распознавать QR, EAN‑13, EAN‑8 и обычный Code 128, печатать собственные QR-этикетки и выгружать остатки в PDF или CSV. Сканирование само по себе не проводит движение.</p></div><div class="help-item"><h3>8. Исправления и границы</h3><p>Разрешённая отмена создаёт обратную запись, а исходная остаётся. ЯРУС — оперативный учёт, не бухгалтерия: здесь нет FIFO, обязательной маркировки, партий и серийных номеров. Для доступа через интернет требуется отдельно настроенный HTTPS.</p></div><div class="help-item"><h3>Нужна помощь?</h3><p>Почта: fixerkrk@yandex.ru<br>Telegram: @bertosh1</p><div class="row wrap"><button class="btn small" data-action="support-email">Написать на почту</button><button class="btn small" data-action="support-telegram">Открыть Telegram</button></div></div><div class="help-item"><h3>Копия до локального восстановления</h3><p>Перед заменой личного склада ЯРУС сохраняет внутреннюю копию. Она не защищает от удаления приложения, поэтому подключите внешний файл или сохраните отдельную копию.</p><button class="btn small" data-action="before-restore" style="margin-top:12px">Выгрузить копию до восстановления</button></div>`,'',true);}
async function logout(){if(queue.length){toast('Сначала отправьте или явно уберите черновики из очереди.','warn');queueModal();return;}if(!confirm('Выйти и удалить сохранённую на этом устройстве копию общего склада? Данные сервера останутся.'))return;
 try{await api('/api/logout',{});}catch(e){if(!e.network&&e.status!==401){toast(e.message,'error');return;}toast('Локальный вход удалён. Без связи серверная сессия не отозвана и истечёт автоматически.','warn');}
 await delKV(activeKey());await delKV(queueKey());delete cfg.token;cfg.mode='local';cfg.demo=false;saveCfg();state=await getKV('local')||null;queue=[];network='local';closeModal(true);$('#app').innerHTML='';page='home';render();}
async function action(name,el){const itemID=el.dataset.id||'',required={operation:'stock','new-item':'catalog','edit-item':'catalog','archive-item':'catalog',import:'catalog','new-place':'places','edit-place':'places','edit-space':'settings',reverse:'reverse',team:'team','make-invite':'team','change-role':'team','disable-user':'team','server-backup':'backup',backup:'full_export','host-transfer':'host_transfer'}[name];if(required&&!can(required)){toast('У вас нет права выполнить это действие.','warn');return;}switch(name){
 case 'close-modal':closeModal();break;
 case 'start-local':closeModal(true);await createLocal();break;
 case 'leave-demo':closeModal(true);cfg.demo=false;saveCfg();await createLocal();break;
 case 'demo':await openDemo();break;
 case 'setup':accountModal('setup');break;
 case 'create-host':createHostModal();break;
 case 'open-host':await openHost();break;
 case 'import-host':importHostModal();break;
 case 'scan-invite':openScanner('invite',true);break;
 case 'connect':case 'login-again':accountModal('login');break;
 case 'account-tab':{const base=$('#account-form input[name=server]')?.value;accountModal(el.dataset.kind,{server:base});break;}
 case 'licenses':modal('Компоненты и лицензии','Открытые компоненты, встроенные в приложение.', '<pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px">'+esc($('#thirdparty-notices').textContent)+'</pre>');break;case 'scan-code':openScanner(el.dataset.target||'lookup');break;case 'label-item':labelModal('item',itemID);break;case 'label-place':labelModal('place',itemID);break;case 'new-item':newItemModal();break;
 case 'edit-item':newItemModal(itemID);break;
 case 'detail':detailModal(itemID);break;
 case 'new-place':placeModal();break;
 case 'edit-place':placeModal(itemID);break;
 case 'edit-space':spaceModal();break;
 case 'operation':operationModal(el.dataset.kind||'in',itemID);break;
 case 'switch-operation':if(!modalDirty||confirm('Сменить тип движения? Введённые поля будут сброшены.'))operationModal(el.dataset.kind,$('#op-item')?.value||itemID);break;
 case 'reverse':reverseModal(itemID);break;
 case 'show-low':stockFilter='low';page='stock';render();break;
 case 'place-stock':placeFilter=itemID;page='stock';stockFilter='available';render();break;
 case 'archive-item':{const x=state.items[itemID];if(x&&confirm(x.archived?'Вернуть товар в каталог?':'Убрать товар в архив? История сохранится.')){const r=await send({id:id(),type:'item',item:{...x,archived:!x.archived}});closeModal(true);toast(r.saved?'Карточка обновлена.':'Изменение ждёт подтверждения.');}break;}
 case 'help':helpModal();break;
 case 'team':await teamModalV11();break;
 case 'make-invite':await makeInviteV11();break;
 case 'copy-invite':await copyText($('#invite-text').value,$('#invite-text'));break;
 case 'change-role':{const role=$('#role-'+itemID)?.value;if(role&&confirm('Изменить уровень доступа этого участника?')){await send({id:id(),type:'user-role',userId:itemID,role});await teamModalV11();}break;}
 case 'disable-user':if(confirm('Отключить доступ этого участника к главному устройству?')){await send({id:id(),type:'disable',userId:itemID});await teamModalV11();}break;
 case 'sync-status':case 'queue':queueModal();break;
 case 'sync-queue':await syncNow(true);queueModal();break;
 case 'retry-queue':{const qe=queue.find(x=>x.command.id===itemID);if(qe){await mutateQueue(q=>q.map(x=>x.command.id===itemID?{...x,error:''}:x));await syncNow(true);queueModal();}break;}
 case 'discard-queue':if(confirm('Убрать этот черновик из очереди? Если сервер уже принял операцию, она останется в истории; удаление черновика её не отменяет.')){await mutateQueue(q=>q.filter(x=>x.command.id!==itemID));queueModal();render();}break;
 case 'backup':await backup();break;
 case 'restore':restoreModal();break;
 case 'portable-create':await createPortableWarehouse();break;
 case 'portable-open':await openPortableWarehouse();break;
 case 'portable-sync':await mirrorPortableState(true);break;
 case 'portable-detach':detachPortableWarehouse();break;
 case 'server-backup':{const r=await api('/api/backup',{});toast(cfg.mode==='host'?'Защищённая внутренняя копия Android обновлена. Для защиты от потери устройства отдельно сохраните JSON-копию или пакет переноса.':'Копия на сервере создана: '+r.filename+'. Перенесите её на отдельное устройство.');break;}
 case 'host-transfer':await hostTransferModal();break;
 case 'export-csv':exportCSV();break;
 case 'export-pdf':stockReportModal();break;
 case 'export-history':exportCSV(true);break;
 case 'import':importModal();break;
 case 'logout':await logout();break;
 case 'dismiss-tips':cfg.tips=false;saveCfg();render();break;
 case 'support-email':openExternal('mailto:fixerkrk@yandex.ru');break;
 case 'support-telegram':openExternal('https://t.me/bertosh1');break;
 case 'download-github':openExternal(DOWNLOAD_URLS.github);break;
 case 'download-yandex':openExternal(DOWNLOAD_URLS.yandex);break;
 case 'download-rustore':openExternal(DOWNLOAD_URLS.rustore);break;
 case 'before-restore':{const s=await getKV('before-restore');if(!s){toast('Такой копии пока нет.','warn');break;}const clean=D.copy(s);delete clean.localSeen;delete clean.me;showExport('YARUS-before-restore.json',JSON.stringify(clean,null,2));break;}
 }}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();if(el.disabled)return;Promise.resolve(action(el.dataset.action,el)).catch(err=>toast(err.message,'error'));return;}const nav=e.target.closest('[data-nav]');if(nav){page=nav.dataset.nav;render();window.scrollTo(0,0);return;}const item=e.target.closest('[data-item]');if(item){detailModal(item.dataset.item);return;}const sf=e.target.closest('[data-stock-filter]');if(sf){stockFilter=sf.dataset.stockFilter;render();return;}const hf=e.target.closest('[data-history-filter]');if(hf){historyFilter=hf.dataset.historyFilter;render();return;}});
document.addEventListener('input',e=>{if(e.target.closest('#modal-root'))modalDirty=true;if(['global-search','stock-search'].includes(e.target.id)){search=e.target.value;page='stock';render();}});
document.addEventListener('change',e=>{if(e.target.matches('.widget-check')){const selected=$$('.widget-check:checked').map(input=>input.value);if(!selected.length){e.target.checked=true;toast('Оставьте хотя бы один виджет.','warn');return;}cfg.widgets=selected;saveCfg();render();return;}switch(e.target.id){case 'place-filter':placeFilter=e.target.value;render();break;case 'category-filter':category=e.target.value;render();break;case 'sort-by':sortBy=e.target.value;render();break;case 'theme-select':cfg.theme=e.target.value;saveCfg();applyTheme();break;case 'dense-check':cfg.dense=e.target.checked;saveCfg();applyTheme();break;case 'tips-check':cfg.tips=e.target.checked;saveCfg();render();break;}});
document.addEventListener('keydown',e=>{if(!yarusScanSession&&e.key==='Enter'&&['stock-search','global-search'].includes(e.target.id)){try{const r=YarusCodes.resolve(state,e.target.value);if(r.kind==='item'){e.preventDefault();detailModal(r.id);return;}if(r.kind==='place'){e.preventDefault();page='stock';placeFilter=r.id;search='';render();return;}}catch(err){if(/^YARUS:/i.test(e.target.value)){toast(err.message,'error');return;}}}if(yarusScanSession)return;if(e.key==='Escape')closeModal();if(e.key==='/'&&!e.target.matches('input,textarea,select')&&!$('#modal-root .modal')){e.preventDefault();if(innerWidth>700)$('#global-search')?.focus();else{page='stock';render();$('#stock-search')?.focus();}}if(e.key==='Enter'&&e.target.matches('[data-item]'))detailModal(e.target.dataset.item);if(e.key==='Tab'&&$('#modal-root .modal')){const all=$$('#modal-root button:not(:disabled),#modal-root input:not(:disabled),#modal-root select:not(:disabled),#modal-root textarea:not(:disabled)').filter(x=>x.offsetParent!==null);if(all.length){if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all[all.length-1].focus();}else if(!e.shiftKey&&document.activeElement===all[all.length-1]){e.preventDefault();all[0].focus();}}}});
let channel;try{channel=new BroadcastChannel('yarus-changes');channel.onmessage=async e=>{if(cfg.mode!=='remote'&&e.data.key===activeKey()){state=await getKV(activeKey());render();}};}catch{}
window.addEventListener('online',()=>syncNow());document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncNow();});
setInterval(()=>{if(!document.hidden)syncNow();},5000);
window.addEventListener('beforeunload',e=>{if(queue.length){e.preventDefault();e.returnValue='Есть неподтверждённые операции.';}});
window.addEventListener('error',e=>{console.error('YARUS client error',e.message);});
async function init(){applyTheme();recordAppDay();try{db=await openDB();setupKey=new URLSearchParams(location.hash.slice(1)).get('setup')||'';if(setupKey)history.replaceState(null,'',location.pathname+location.search);if(cfg.mode==='host'&&(!window.YarusAndroidHost||!YarusAndroidHost.info().exists)){cfg.mode='local';delete cfg.token;saveCfg();}if(cfg.mode==='host')YarusAndroidHost.activate();state=await getKV(activeKey())||null;if(state&&cfg.mode!=='remote'&&cfg.mode!=='host'&&!state.space.id){state=await migrateLocalSpace();}queue=cfg.mode==='remote'?(await getKV(queueKey())||[]):[];network=cfg.mode==='remote'?'connecting':cfg.mode==='host'?'host':'local';lastSync=state?.savedAt||'';render();if(cfg.mode==='remote')await syncNow();if(cfg.mode==='host'){try{const snapshot=await api('/api/state');await acceptState(snapshot);render();}catch(e){state=null;render();if(e.status===401)hostLoginModal();else toast(e.message,'error');}}}catch(e){$('#app').innerHTML=`<div class="welcome-form" style="min-height:100dvh"><div class="welcome-inner">${brand()}<h2 style="margin-top:30px">Хранилище недоступно</h2><p>ЯРУС не будет делать вид, что сохраняет данные. Разрешите локальное хранилище, отключите приватный режим или откройте приложение в обычном режиме.</p><div class="notice">${esc(e.message)}</div></div></div>`;}}
function migrateLocalSpace(){return new Promise((resolve,reject)=>{const tx=db.transaction("kv","readwrite"),store=tx.objectStore("kv"),req=store.get(activeKey());let value;req.onsuccess=()=>{value=req.result;if(value&&!value.space.id){store.put(D.copy(value),"before-0.10-migration:"+activeKey());value.space.id=id();store.put(value,activeKey());}};tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Не удалось сохранить идентификатор склада."));});}
init();
